"""Focused rounds keep broad narrative observations separate from effect verification."""
import ast,collections,hashlib,json
from pathlib import Path
F=Path(__file__).resolve().parent;B=F.parent

def main():
 tree=ast.parse((B/'scripts/prepare_adjudication.py').read_text());lead=next(n.value for n in ast.walk(tree) if isinstance(n,ast.Constant) and isinstance(n.value,str) and n.value.startswith('Adjudicate paper-statistics disagreements'))
 rows=json.loads((B/'parent_rows.json').read_text());inputs={r['audit_id']:r for p in (F/'validation_inputs').glob('*.json') for r in json.loads(p.read_text()) if r['target_side']=='replication'};accepted={str(Path(r['text_path']).resolve()):r for r in json.loads((F/'accepted_sources.json').read_text()).values()};groups=collections.defaultdict(list);pairs={(r['audit_id'],'reported_success') for r in json.loads((F/'narrative_scope_flags.json').read_text())};pairs|={(aid,field) for aid in [1596,1597] for field in ['n_r','es_value_r']};pairs|={(aid,'n_r') for aid in [1552,1553]}
 previous=[r for p in (B/'adjudications').glob('validated_drivefollowup_*.json') for r in json.loads(p.read_text())]
 for aid,field in sorted(pairs):
  x=json.loads((B/'extractions'/f'{aid}.json').read_text());row=rows[aid-1];v=x['reported_success'] if field=='reported_success' else x['replication'][{'n_r':'n','es_value_r':'es'}[field]];path=str(Path(v['source_path']).resolve());a=accepted[path];prior=[r for r in previous if r['audit_id']==aid and r['field']==field]
  item={'audit_id':aid,'field':field,'comparison':'mismatched_target','shipped':row.get(field),'shipped_metric':row.get('es_type_r') if field=='es_value_r' else None,'shipped_bound':None,'blind':v,'scope_note':'The numeric target is unresolved or explicitly mismatched; the author label was retained as an observation. Require unique individual-effect mapping; do not transfer an agreeing overall paper/study label.','locator':inputs[aid],'work_key':row['work_key'],'coding_context':{'description':row.get('description'),'es_repr':row.get('es_repr_r'),'reported_success_quote':row.get('reported_success_quote'),'coded_statistics_for_target_selection':{f:row.get(f) for f in ['n_r','es_value_r','es_type_r','pval_value_r','pval_type_r']}},'prior_findings':prior,'blind_target_description':x['replication']['target_description'],'blind_extraction_notes':x['notes'],'source_version_note':a['source_version'],'primary_source_pdf_path':a['source_pdf_path'],'parent_objection':'An agreement with a printed number or broad author label cannot resolve a different contrast, sample, model or outcome. Independently establish a documented mapping using target metadata and primary evidence, otherwise undeterminable. For1596/1597 distinguish initial intervention within all participants from a no-intervention control comparison; do not select the slope by numeric coincidence. For1552/1553 distinguish all instructed participants from Tseltal-only follow-up models and the original study4 replication portion from extension manipulations.'}
  groups[path].append(item)
 q=json.loads((F/'adjudication_queue.json').read_text());history={json.loads(l)['key'] for l in (F/'adjudication_tasks.jsonl').read_text().splitlines() if l}
 for path,items in groups.items():
  text=lead+'\n\n'+json.dumps(items,indent=2,ensure_ascii=False)+'\n\nFOCUSED SCOPE ROUND: Carry forward original brief, prior findings and unresolved objections. For reported_success return effect_specific_verdict_confirmed true ONLY with a unique defensible row/outcome mapping and the authors own applicable narrative. Include exact primary quotations. Numeric agreement alone never establishes sample/contrast identity. No commands or writes; whole reply under ## Answer.\n';key='drivefollowup_'+hashlib.sha256(text.encode()).hexdigest()[:16];p=B/'adjudications'/f'prompt_{key}.txt';p.write_text(text)
  if key not in history:q.append({'key':key,'source_path':path,'prompt':str(p.resolve()),'output':str((B/'adjudications'/f'raw_{key}.txt').resolve()),'items':[{'audit_id':r['audit_id'],'field':r['field']} for r in items],'prompt_bytes':len(text.encode()),'focused_review':True,'scope_round':1})
 (F/'adjudication_queue.json').write_text(json.dumps(q,indent=2)+'\n');print('focused scope groups',len(groups),'field reviews',len(pairs))
if __name__=='__main__':main()
